async function loadMe(){S.me=(await api("/api/me")).user}
async function loadStudioInitial(){const d=await api("/api/studio");S.me=d.user;S.shop=d.shop}
async function bootApp(){try{await loadMe();await loadCommunities();await loadDms();await loadStudioInitial();applyPreferences();await loadMissions();S.socket=io({transports:["polling"]});window.__ORBIT_APP_STATE__=S;bindSocket();await refreshNotificationCount();$("#boot").innerHTML="";$("#app").classList.remove("hidden");render()}catch(e){if(e.status===401)return authScreen("signin");$("#boot").innerHTML='<div class="empty-state"><div class="empty-box"><h2>ORBIT could not start</h2><p>'+esc(e.message)+'</p><button class="btn primary" id="retryBoot">Retry</button></div></div>';$("#retryBoot").onclick=bootApp}}
function bindSocket(){S.socket.on("message:new",m=>{if(m.conversation_id===S.activeConversation){S.messages.push(m);if($("#messageList")){$("#messageList").innerHTML=renderMessageHtml();$("#messageList").scrollTop=$("#messageList").scrollHeight}}});S.socket.on("typing",x=>{if(x.conversationId===S.activeConversation&&x.isTyping)$("#callStatus").textContent="Someone is typing…";});S.socket.on("notification:new",n=>{toast(n.notification?.title||"Notification",n.notification?.body||"");refreshNotificationCount()});S.socket.on("call:incoming",d=>showIncoming(d));S.socket.on("call:participants",p=>p.forEach(x=>createPeer(x.socketId,true,x.user)));S.socket.on("call:participant-joined",p=>createPeer(p.socketId,false,p.user));S.socket.on("rtc:offer",handleOffer);S.socket.on("rtc:answer",handleAnswer);S.socket.on("rtc:ice",handleIce);S.socket.on("screen:offer",handleScreenOffer);S.socket.on("screen:answer",handleScreenAnswer);S.socket.on("screen:ice",handleScreenIce);S.socket.on("screen:stop",d=>{if(d?.from)removeRemoteScreen(d.from)});S.socket.on("call:participant-left",p=>removePeer(p.socketId));S.socket.on("presence:update",()=>{});}
function showIncoming(d){S.pendingCall=d;$("#incomingName").textContent=d.caller?.displayName||d.caller?.username||"Incoming call";$("#incomingMode").textContent=d.mode==="voice"?"Voice call":"Video call";const host=$("#incomingAvatar");if(host){const a=avatar(d.caller);host.className=a.match(/class="([^"]+)"/)?.[1]||"avatar";host.innerHTML=d.caller?.avatarUrl?'<img src="'+esc(d.caller.avatarUrl)+'" alt="">':esc(letter(d.caller))}$("#incoming").classList.remove("hidden")}
$("#acceptCall").onclick=()=>{if(!S.pendingCall)return;const d=S.pendingCall;$("#incoming").classList.add("hidden");startCall(d.conversationId,d.mode,false);S.pendingCall=null};
$("#declineCall").onclick=()=>{$("#incoming").classList.add("hidden");S.pendingCall=null};
function setCallMode(mode){const w=$("#callWindow");if(!w)return;w.classList.remove("mode-focus","mode-gallery","mode-cinema");w.classList.add("mode-"+mode);["Focus","Gallery","Cinema"].forEach(x=>{const b=$("#callMode"+x),bb=$("#callMode"+x+"Bottom");if(b)b.classList.toggle("active",x.toLowerCase()===mode);if(bb)bb.classList.toggle("active",x.toLowerCase()===mode)})}
function updateCallDuration(){if(!S.call?.startedAt)return;const sec=Math.max(0,Math.floor((Date.now()-S.call.startedAt)/1000));const mm=String(Math.floor(sec/60)).padStart(2,"0"),ss=String(sec%60).padStart(2,"0");if($("#callDuration"))$("#callDuration").textContent=mm+":"+ss}
function renderCallParticipants(speakerId=null){const list=$("#callParticipantList"),count=$("#callParticipantCount");if(!list||!S.call)return;const people=[{id:"local",user:S.me||{},local:true},...Object.values(S.call.peers||{}).map(p=>({id:p.socketId,user:p.user||{},local:false}))];if(count)count.textContent=people.length+" Participant"+(people.length===1?"":"s");list.innerHTML=people.map(p=>{const muted=p.local?!(S.call.stream?.getAudioTracks?.()[0]?.enabled):false;const camOff=p.local?!S.call.stream?.getVideoTracks?.()[0]?.enabled:!!document.querySelector("#tile-"+p.id+".is-video-off");return '<button class="call-participant '+(speakerId===p.id?"is-speaking ":"")+'" data-call-peer="'+esc(p.id)+'">'+avatar(p.user)+'<span class="call-participant-copy"><strong>'+esc(p.user?.displayName||p.user?.username||"Guest")+(p.local?" <span style=\"color:var(--cyan)\">(You)</span>":"")+'</strong><span>'+(speakerId===p.id?"Speaking now":"Ready")+'</span></span><span class="call-participant-state '+(muted?"muted":"live")+'">'+(muted?"🔇":"🎙")+(camOff?" · ○":" · ◉")+'</span></button>'}).join("");$("#callParticipantList [data-call-peer]").forEach(b=>b.onclick=()=>focusCallParticipant(b.dataset.callPeer))}
function focusCallParticipant(id){const tile=$("#tile-"+id);if(!tile)return;document.querySelectorAll(".video-tile").forEach(x=>x.classList.remove("call-focus-selected"));tile.classList.add("call-focus-selected");setCallMode("focus");tile.scrollIntoView({behavior:"smooth",block:"center",inline:"center"});renderCallParticipants();setTimeout(()=>tile.classList.remove("call-focus-selected"),1800)}
function updateSpeakingUi(id){document.querySelectorAll(".video-tile").forEach(t=>{t.classList.toggle("smart-speaker",t.id==="tile-"+id);if(t.id!=="tile-"+id)t.querySelector(".smart-speaker-badge")?.remove()});if(id){const tile=$("#tile-"+id);if(tile&&!tile.querySelector(".smart-speaker-badge")){const b=document.createElement("span");b.className="smart-speaker-badge";b.textContent="Speaking";tile.appendChild(b)}}$("#callParticipantList [data-call-peer]").forEach(b=>b.classList.toggle("is-speaking",b.dataset.callPeer===id))}
function callRms(analyser,data){analyser.getByteTimeDomainData(data);let sum=0;for(let i=0;i<data.length;i++){const v=(data[i]-128)/128;sum+=v*v}return Math.sqrt(sum/data.length)}
function startCallAudioMonitor(id,stream){if(!S.call||!stream?.getAudioTracks?.().length||S.call.audioMonitors?.[id])return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;S.call.audioContext=S.call.audioContext||new AC();S.call.audioContext.resume?.();const source=S.call.audioContext.createMediaStreamSource(stream),analyser=S.call.audioContext.createAnalyser();analyser.fftSize=256;analyser.smoothingTimeConstant=.78;source.connect(analyser);S.call.audioMonitors=S.call.audioMonitors||{};S.call.audioMonitors[id]={source,analyser,data:new Uint8Array(analyser.fftSize)}}catch(e){console.warn("ORBIT audio monitor unavailable",e)}}
function runSmartSpeaker(){if(!S.call)return;let best=null,bestLevel=0;for(const [id,m] of Object.entries(S.call.audioMonitors||{})){const level=callRms(m.analyser,m.data);m.level=level;if(level>bestLevel){bestLevel=level;best=id}}if(bestLevel<.055)best=null;if(best!==S.call.smartSpeaker){S.call.smartSpeaker=best;updateSpeakingUi(best);renderCallParticipants(best)}S.call.speakerFrame=requestAnimationFrame(runSmartSpeaker)}
function bindCallParticipantDnD(){const stage=$("#callStage");if(!stage||stage.__orbitDnd)return;stage.__orbitDnd=true;stage.addEventListener("dragstart",e=>{const tile=e.target.closest(".video-tile");if(!tile||tile.classList.contains("screen-share"))return;tile.classList.add("dragging");e.dataTransfer?.setData("text/plain",tile.id);if(e.dataTransfer)e.dataTransfer.effectAllowed="move"});stage.addEventListener("dragend",e=>e.target.closest(".video-tile")?.classList.remove("dragging"));stage.addEventListener("dragover",e=>{e.preventDefault();const dragging=stage.querySelector(".video-tile.dragging"),target=e.target.closest(".video-tile");if(!dragging||!target||target===dragging||target.classList.contains("screen-share"))return;const r=target.getBoundingClientRect();stage.insertBefore(dragging,e.clientY<r.top+r.height/2?target:target.nextSibling)})}

function showCallUi(title,mode){const w=$("#callWindow");if(w){w.classList.remove("minimized","fullscreen");setCallMode("gallery");w.style.left="";w.style.top=""}$("#callTitle").textContent=title;$("#callStatus").innerHTML='<span class="call-live-dot"></span>'+(mode==="voice"?"Voice · live":"Video · live");$("#callOverlay").classList.remove("hidden");S.call.startedAt=Date.now();clearInterval(S.call.durationTimer);S.call.durationTimer=setInterval(updateCallDuration,1000);updateCallDuration()}
async function startCall(roomId,mode="video",invite=true){try{if(S.call)endCall();const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==="video"});S.call={roomId,mode,stream,peers:{},screen:null,screenPeers:{},audioMonitors:{},speakerFrame:null,smartSpeaker:null,audioContext:null};showCallUi(S.activeDm?.otherUser?.displayName||S.activeCommunity?.name||"ORBIT Call",mode);mountLocal(stream);renderCallParticipants();bindCallParticipantDnD();startCallAudioMonitor("local",stream);cancelAnimationFrame(S.call.speakerFrame);S.call.speakerFrame=requestAnimationFrame(runSmartSpeaker);if(invite)S.socket.emit("call:invite",{conversationId:roomId,mode});S.socket.emit("call:join",{roomId,mode})}catch(e){toast("Call",e.name==="NotAllowedError"?"Camera/microphone permission was blocked.":e.message||"Camera/microphone permission failed")}}
function mountLocal(stream){const id="local";let tile=$("#tile-"+id);if(!tile){tile=document.createElement("div");tile.className="video-tile call-main";tile.id="tile-"+id;tile.draggable=true;$("#callStage").appendChild(tile)}tile.innerHTML='<div class="call-avatar">'+avatar(S.me)+'</div><video autoplay muted playsinline></video><div class="video-label">'+esc(S.me?.displayName||"You")+'</div><div class="call-presence live" id="localCamState">◉</div>';const video=tile.querySelector("video");video.srcObject=stream;video.onloadeddata=()=>tile.classList.remove("is-video-off");const cam=stream.getVideoTracks?.()[0];tile.classList.toggle("is-video-off",!cam||cam.enabled===false)}
function localPreview(stream){const video=$("#tile-local video");if(video)video.srcObject=stream}
async function createPeer(socketId,initiator,user){if(!S.call)return;const pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});const remoteStream=new MediaStream();S.call.peers[socketId]={pc,user,socketId,remoteStream,cameraSender:null,negotiating:false};renderCallParticipants();S.call.stream.getAudioTracks().forEach(t=>pc.addTrack(t,S.call.stream));const cameraTransceiver=pc.addTransceiver("video",{direction:"sendrecv"});S.call.peers[socketId].cameraSender=cameraTransceiver.sender;const currentVideo=S.call.stream.getVideoTracks?.()[0]||null;if(currentVideo)await cameraTransceiver.sender.replaceTrack(currentVideo);pc.onicecandidate=e=>{if(e.candidate)S.socket.emit("rtc:ice",{to:socketId,candidate:e.candidate})};pc.onconnectionstatechange=()=>{if(["failed","closed"].includes(pc.connectionState))removePeer(socketId)};pc.ontrack=e=>{if(!e.track)return;if(!remoteStream.getTracks().some(t=>t.id===e.track.id))remoteStream.addTrack(e.track);mountRemote(socketId,remoteStream,user);if(e.track.kind==="audio"){ensureRemoteAudio(socketId,remoteStream);startCallAudioMonitor(socketId,remoteStream);e.track.onunmute=()=>ensureRemoteAudio(socketId,remoteStream)}if(e.track.kind==="video"){const tile=$("#tile-"+socketId);e.track.onmute=()=>tile?.classList.add("is-video-off");e.track.onunmute=()=>tile?.classList.remove("is-video-off");if(e.track.muted)tile?.classList.add("is-video-off")}};if(initiator){const off=await pc.createOffer();await pc.setLocalDescription(off);S.socket.emit("rtc:offer",{to:socketId,offer:pc.localDescription})}if(S.call?.screen){const track=S.call.screen.getVideoTracks?.()[0];if(track)await startScreenPeer(socketId,track)}}
function ensureRemoteAudio(id,stream){let audio=$("#remote-audio-"+id);if(!audio){audio=document.createElement("audio");audio.id="remote-audio-"+id;audio.autoplay=true;audio.playsInline=true;audio.controls=false;audio.muted=false;audio.volume=1;audio.setAttribute("aria-hidden","true");audio.style.position="fixed";audio.style.width="1px";audio.style.height="1px";audio.style.opacity="0";audio.style.pointerEvents="none";audio.style.left="-9999px";document.body.appendChild(audio)}if(audio.srcObject!==stream)audio.srcObject=stream;const p=audio.play();if(p?.catch)p.catch(()=>{audio.dataset.blocked="1"});return audio}
function mountRemote(id,stream,user){let tile=$("#tile-"+id);if(!tile){tile=document.createElement("div");tile.className="video-tile";tile.id="tile-"+id;tile.draggable=true;tile.innerHTML='<div class="call-avatar">'+avatar(user||{})+'</div><video autoplay playsinline></video><div class="video-label">'+esc(user?.displayName||user?.username||"Guest")+'</div><div class="call-presence muted">🎙</div>';$("#callStage").appendChild(tile);bindCallVideoTrackUi(tile)}const video=tile.querySelector("video");if(video){video.autoplay=true;video.playsInline=true;video.muted=false;if(video.srcObject!==stream)video.srcObject=stream;video.play?.().catch(()=>{})}ensureRemoteAudio(id,stream)}
function bindCallVideoTrackUi(tile){const video=tile.querySelector("video");if(!video||video.__orbitBound)return;video.__orbitBound=true;video.addEventListener("playing",()=>tile.classList.remove("is-video-off"));video.addEventListener("pause",()=>tile.classList.add("is-video-off"))}
function mountRemoteScreen(id,stream,user){let tile=$("#screen-"+id);if(!tile){tile=document.createElement("div");tile.className="video-tile screen-share";tile.id="screen-"+id;tile.innerHTML='<div class="call-avatar">'+avatar(user||{})+'</div><video autoplay playsinline></video><div class="video-label">Screen share · '+esc(user?.displayName||user?.username||"Guest")+'</div>';$("#callStage").appendChild(tile)}const video=tile.querySelector("video");if(video&&video.srcObject!==stream){video.srcObject=stream;video.play?.().catch(()=>{})}tile.classList.remove("hidden")}
function setRemoteScreen(id,active){const tile=$("#screen-"+id);if(tile)tile.classList.toggle("hidden",!active)}
async function handleOffer(d){if(!S.call)return;if(!S.call.peers[d.from])await createPeer(d.from,false,d.fromUser||{});const p=S.call.peers[d.from];await p.pc.setRemoteDescription(d.offer);const ans=await p.pc.createAnswer();await p.pc.setLocalDescription(ans);S.socket.emit("rtc:answer",{to:d.from,answer:ans})}
async function startScreenPeer(to,track){if(!S.call||!track)return;const old=S.call.screenPeers?.[to];if(old?.pc)try{old.pc.close()}catch{};S.call.screenPeers[to]={pc:null,local:true,pendingIce:[]};const pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});S.call.screenPeers[to].pc=pc;pc.addTrack(track,new MediaStream([track]));pc.onicecandidate=e=>{if(e.candidate)S.socket.emit("screen:ice",{to,candidate:e.candidate})};pc.onconnectionstatechange=()=>{if(["failed","closed"].includes(pc.connectionState)){if(S.call?.screenPeers?.[to]?.pc===pc)delete S.call.screenPeers[to]}};const offer=await pc.createOffer();await pc.setLocalDescription(offer);S.socket.emit("screen:offer",{to,offer:pc.localDescription})}
async function handleScreenOffer(d){if(!S.call)return;let p=S.call.screenPeers[d.from];if(!p)p=S.call.screenPeers[d.from]={pc:null,local:false,pendingIce:[]};if(p.pc)try{p.pc.close()}catch{};const pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});p.pc=pc;p.local=false;pc.onicecandidate=e=>{if(e.candidate)S.socket.emit("screen:ice",{to:d.from,candidate:e.candidate})};pc.ontrack=e=>{if(e.track){const stream=e.streams?.[0]||new MediaStream([e.track]);mountRemoteScreen(d.from,stream,d.fromUser||{})}};pc.onconnectionstatechange=()=>{if(["failed","closed"].includes(pc.connectionState))removeRemoteScreen(d.from)};await pc.setRemoteDescription(d.offer);const pending=p.pendingIce.splice(0);for(const candidate of pending){try{await pc.addIceCandidate(candidate)}catch{}};const ans=await pc.createAnswer();await pc.setLocalDescription(ans);S.socket.emit("screen:answer",{to:d.from,answer:pc.localDescription})}
async function handleScreenAnswer(d){const p=S.call?.screenPeers?.[d.from];if(!p?.pc)return;await p.pc.setRemoteDescription(d.answer);const pending=p.pendingIce?.splice(0)||[];for(const candidate of pending){try{await p.pc.addIceCandidate(candidate)}catch{}}}
async function handleScreenIce(d){if(!S.call||!d?.from||!d?.candidate)return;const p=S.call.screenPeers[d.from]||(S.call.screenPeers[d.from]={pc:null,local:false,pendingIce:[]});if(!p.pc||!p.pc.remoteDescription?.type){p.pendingIce.push(d.candidate);return}try{await p.pc.addIceCandidate(d.candidate)}catch{}}
function removeRemoteScreen(id){const p=S.call?.screenPeers?.[id];if(p?.pc)try{p.pc.close()}catch{};if(S.call?.screenPeers)delete S.call.screenPeers[id];$("#screen-"+id)?.remove()}
async function handleAnswer(d){const p=S.call?.peers?.[d.from];if(p)await p.pc.setRemoteDescription(d.answer)}
async function handleIce(d){const p=S.call?.peers?.[d.from];if(p)try{await p.pc.addIceCandidate(d.candidate)}catch{}}
function removePeer(id){const m=S.call?.audioMonitors?.[id];try{m?.source?.disconnect();m?.analyser?.disconnect()}catch{}if(S.call?.audioMonitors)delete S.call.audioMonitors[id];const a=$("#remote-audio-"+id);if(a){a.pause?.();a.srcObject=null;a.remove()}const sp=S.call?.screenPeers?.[id];if(sp?.pc)try{sp.pc.close()}catch{}if(S.call?.screenPeers)delete S.call.screenPeers[id];S.call?.peers?.[id]?.pc?.close();delete S.call?.peers?.[id];$("#tile-"+id)?.remove();$("#screen-"+id)?.remove();renderCallParticipants();if(S.call?.smartSpeaker===id){S.call.smartSpeaker=null;updateSpeakingUi(null)}}
