$("#callModeFocusBottom")?.addEventListener("click",()=>setCallMode("focus"));$("#callModeGalleryBottom")?.addEventListener("click",()=>setCallMode("gallery"));$("#callModeCinemaBottom")?.addEventListener("click",()=>setCallMode("cinema"));
